ops=[]
def replace(before,after):
 global s
 if s.count(before)!=1: raise ValueError('ambiguous proposal preimage')
 s=s.replace(before,after);ops.append({'before':before,'after':after})
replace("import { loadOwnerCurrentRepairs } from './step5-owner-current-repairs.mjs';", "import { loadOwnerCurrentRepairs } from './step5-owner-current-repairs.mjs';\nimport { createdMaintenanceBasis } from './step5-created-maintenance-cert.mjs';")
