replace("    const frontier=gateFrontier(root,run),scoped=saved.items.filter(row=>frontier.has(row.id));", "    const frontier=gateFrontier(root,run),maintained=new Set((saved.maintenance_certifications??[]).map(row=>row.id));\n    const scoped=saved.items.filter(row=>frontier.has(row.id)||maintained.has(row.id));")
replace("  for(const id of changed) if(!reviewed.has(id)&&priorItems.get(id)?.guard_sha256!==current[id])throw Error(`uncertified change ${id}`);", "  // A completed native outside-maintenance repair is a separate typed basis,\n  // never a synthesized frontier review or a rewritten creation certificate.\n  const maintenance=createdMaintenanceBasis(root,run,phase,round,{prior,result,progress,eligible,items:library,current});\n  for(const id of changed) if(!reviewed.has(id)&&!maintenance.basis.has(id)&&priorItems.get(id)?.guard_sha256!==current[id])throw Error(`uncertified change ${id}`);")
replace("  const evidence={...(prior?.evidence??{}),...(sourceResult?.evidence??{}),...result.evidence};", "  const evidence={...(prior?.evidence??{}),...(sourceResult?.evidence??{}),...result.evidence,...maintenance.evidence};")
replace("  const items=ids.map(id=>({id,...contexts.get(id),guard_sha256:current[id],reason:reviewed.get(id)?.reason??priorItems.get(id)?.reason}));", "  const items=ids.map(id=>({id,...contexts.get(id),guard_sha256:current[id],reason:reviewed.get(id)?.reason??maintenance.basis.get(id)?.reason??priorItems.get(id)?.reason}));")
replace("  const certificate={version:2,run,phase,round,at:new Date().toISOString(),items,creations,evidence,changed,", "  const certificate={version:2,run,phase,round,at:new Date().toISOString(),items,creations,evidence,changed,\n    ...(maintenance.records.length?{maintenance_certifications:maintenance.records}:{}),")
