for f in ['step5-workflow.mjs','WORKFLOW.md']:
 (p/(f+'.diff')).write_text(''.join(difflib.unified_diff((p/'before'/f).read_text().splitlines(True),(p/'proposed'/f).read_text().splitlines(True),fromfile=f,tofile=f)))
packet={'version':1,'status':'research-only first-cycle proposal; unexecuted; no hashes calculated','run':'numerical-optimization-dynamics-2026-10-16','install_boundary':'actual paused drained boundary; root only','operations':[{'path':'tools/step5-workflow.mjs','exact_preimage':str(p/'before/step5-workflow.mjs'),'proposed':str(p/'proposed/step5-workflow.mjs'),'replacements':ops},{'path':'WORKFLOW.md','exact_preimage':str(p/'before/WORKFLOW.md'),'proposed':str(p/'proposed/WORKFLOW.md'),'append':addition},{'path':'tools/step5-created-maintenance-cert.mjs','must_be_absent':True,'proposed':str(p/'proposed/step5-created-maintenance-cert.mjs')}]}
